-- FIFA World Cup 2026 104-match seed for the current public nickname app.
-- Stores kickoff times in UTC. The frontend displays them in Asia/Riyadh.
--
-- Sources checked:
-- - FIFA/Wikipedia match schedule pages for local dates/times, venues, and knockout placeholders.
-- - SB Nation group-stage schedule where times are listed in Eastern time.
--
-- This script updates deterministic seed ids 2026001..2026104. It does not
-- delete user predictions. If you have old test rows outside this id range,
-- remove them manually after checking they are not needed.

begin;

alter table public.matches
  add column if not exists match_number integer,
  add column if not exists stadium text,
  add column if not exists city text,
  add column if not exists country text,
  add column if not exists home_penalties integer,
  add column if not exists away_penalties integer,
  add column if not exists winner text;

create unique index if not exists matches_match_number_unique_idx
on public.matches (match_number)
where match_number is not null;

